('a660ddb6-4c35-45ec-ba86-055637fe2a5e','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_EXTREMO":"RAAPIDO BUENO EN GENERAR DUELOS, EJECUIONES BAJAS. IMPORTANTE PARA JUEGO INTERIOR","car_obs_extremo":"RAAPIDO BUENO EN GENERAR DUELOS, EJECUIONES BAJAS. IMPORTANTE PARA JUEGO INTERIOR"}'),
('a7349aed-53fb-4a14-a18a-1ffb66429bcb','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"Central derecho de perfil. Hoy juega como central izquierdo en línea de 3. Contundente y sólido en defensa. Potente. Presenta cierto desorden y no siempre toma buenas referencias en lado opuesto.","car_obs_central":"Central derecho de perfil. Hoy juega como central izquierdo en línea de 3. Contundente y sólido en defensa. Potente. Presenta cierto desorden y no siempre toma buenas referencias en lado opuesto."}'),
('aaf6443e-a00d-405c-9acf-d79841c30678','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE","car_obs_MEDIOCENTRO":"Mediocentro de muy buena dinámica, ofreciendo bastante recorrido y siendo un jugador de aporte considerablemente positivo en ataque, además cuenta con buen centro en pelotas quietas, hay que seguirlo de cerca.","car_obs_mediocentro":"Mediocentro de muy buena dinámica, ofreciendo bastante recorrido y siendo un jugador de aporte considerablemente positivo en ataque, además cuenta con buen centro en pelotas quietas, hay que seguirlo de cerca."}'),
('add27548-a434-470f-a138-a4d6cc187e80','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_LATERAL":"Es un jugador que puede aportar tanto de lateral derecho en línea de 4 o también cómo stopper por derecha en línea de 3. Da flexibilidad táctica en el bloque defensivo, rinde muy bien ofreciendo apoyos y coberturas, no es un jugador técnico, pero si tácticamente muy cumplidor.","car_obs_lateral":"Es un jugador que puede aportar tanto de lateral derecho en línea de 4 o también cómo stopper por derecha en línea de 3. Da flexibilidad táctica en el bloque defensivo, rinde muy bien ofreciendo apoyos y coberturas, no es un jugador técnico, pero si tácticamente muy cumplidor."}'),
