('b419a691-2d16-49a3-befa-975bf4df8c2c','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"JUGANDO COMO CENTRAL POR DERECHA EN LINEA DE 5, ACERTADO EN DUELOS,","car_obs_central":"JUGANDO COMO CENTRAL POR DERECHA EN LINEA DE 5, ACERTADO EN DUELOS,"}'),
