('062b24eb-6440-4960-8d4b-e37827f88db1','{"val_partido":"3. RELEVANCIA NORMAL","att_CENTRAL_referencia_posicional":"4","att_CENTRAL_contundencia_en_duelo_aereo":"3","att_CENTRAL_anticipacion":"4","att_CENTRAL_cierres":"4","att_CENTRAL_duelos_defensivos":"4","att_CENTRAL_contundencia_en_duelos_defensivos":"4","att_CENTRAL_inicio_de_juego":"5","att_obs_CENTRAL":"Central de muy bueno juego de pies, sale bien antes presiones y busca filtrar pases en campo rival. Comete pocos errores con la pelota dominada e incluso se atreve a conducir o intentar avanzar con paredes ante bloques bajos. Tiene buena velocidad y es intuitivo al momento de marcar a campo abierto.","tac_trans_da":"4","tac_trans_ad":"4","att_central_referencia_posicional":"4","att_central_contundencia_en_duelo_aereo":"3","att_central_anticipacion":"4","att_central_cierres":"4","att_central_duelos_defensivos":"4","att_central_contundencia_en_duelos_defensivos":"4","att_central_inicio_de_juego":"5","att_obs_central":"Central de muy bueno juego de pies, sale bien antes presiones y busca filtrar pases en campo rival. Comete pocos errores con la pelota dominada e incluso se atreve a conducir o intentar avanzar con paredes ante bloques bajos. Tiene buena velocidad y es intuitivo al momento de marcar a campo abierto."}'),
('42a78f38-852f-45e8-a0d8-94173ac3c91a','{"val_partido":"4. ALTA RELEVANCIA","att_CENTRAL_referencia_posicional":"4","att_CENTRAL_contundencia_en_duelo_aereo":"4","att_CENTRAL_anticipacion":"4","att_CENTRAL_cierres":"3","att_CENTRAL_duelos_defensivos":"4","att_CENTRAL_contundencia_en_duelos_defensivos":"3","att_CENTRAL_inicio_de_juego":"4","att_obs_CENTRAL":"Defensa central de buena salida de balón, pase inicial, buen juego aéreo y lectura para anticipar.","tac_trans_da":"4","tac_trans_ad":"3","att_central_referencia_posicional":"4","att_central_contundencia_en_duelo_aereo":"4","att_central_anticipacion":"4","att_central_cierres":"3","att_central_duelos_defensivos":"4","att_central_contundencia_en_duelos_defensivos":"3","att_central_inicio_de_juego":"4","att_obs_central":"Defensa central de buena salida de balón, pase inicial, buen juego aéreo y lectura para anticipar."}'),
('ec5d1cd0-247d-4c3e-9e19-4468abbffbb1','{"val_partido":"3. RELEVANCIA NORMAL","att_CENTRAL_referencia_posicional":"3","att_CENTRAL_contundencia_en_duelo_aereo":"3","att_CENTRAL_anticipacion":"4","att_CENTRAL_cierres":"4","att_CENTRAL_duelos_defensivos":"3","att_CENTRAL_contundencia_en_duelos_defensivos":"3","att_CENTRAL_inicio_de_juego":"4","att_obs_CENTRAL":"Central de correcta salida de balón, sobre todo con pase de inicio con criterio, ejecuta bien los cierres y coberturas, no es tanto de duelos físicos o de imponerse en el juego aéreo.","tac_trans_da":"3","tac_trans_ad":"3","att_central_referencia_posicional":"3","att_central_contundencia_en_duelo_aereo":"3","att_central_anticipacion":"4","att_central_cierres":"4","att_central_duelos_defensivos":"3","att_central_contundencia_en_duelos_defensivos":"3","att_central_inicio_de_juego":"4","att_obs_central":"Central de correcta salida de balón, sobre todo con pase de inicio con criterio, ejecuta bien los cierres y coberturas, no es tanto de duelos físicos o de imponerse en el juego aéreo."}'),
('2b17049c-c467-4b02-887f-8d5a62c866e8','{"val_partido":"3. RELEVANCIA NORMAL","car_obs_CENTRAL":"Central de muy buen manejo de pelota, filtró varios pases en campo rival. Tiene un buen pase diagonal para activar al lateral/extremo con trazos largos. Defensivamente se mostró fuerte en el duelo y siempre cercano al delantero, así como imponente por arriba. Muy interesante","car_obs_central":"Central de muy buen manejo de pelota, filtró varios pases en campo rival. Tiene un buen pase diagonal para activar al lateral/extremo con trazos largos. Defensivamente se mostró fuerte en el duelo y siempre cercano al delantero, así como imponente por arriba. Muy interesante"}'),
('a0a8797e-18e1-482c-a9e9-55bead62a765','{"val_partido":"3. RELEVANCIA NORMAL","car_obs_CENTRAL":"Central jóven de buena proyección a futuro, muestra buena personalidad para liderar su defensa, posee buen pase inicial, atento a coberturas y tratar de anticipar, todavía debe mejorar su juego aéreo, cumple pero podría ser mejor para imponerse en esos duelos, en velocidad por momentos no muestra tanto sprint a campo abierto, pero hay partidos que se lo ve mejor en esa faceta, hay que seguirlo de cerca y ver cómo evoluciona, perfil interesante para observar.","car_obs_central":"Central jóven de buena proyección a futuro, muestra buena personalidad para liderar su defensa, posee buen pase inicial, atento a coberturas y tratar de anticipar, todavía debe mejorar su juego aéreo, cumple pero podría ser mejor para imponerse en esos duelos, en velocidad por momentos no muestra tanto sprint a campo abierto, pero hay partidos que se lo ve mejor en esa faceta, hay que seguirlo de cerca y ver cómo evoluciona, perfil interesante para observar."}'),
('5f38cdd0-dc65-4747-ae8b-b0a9dbbd241e','{"val_partido":"4. ALTA RELEVANCIA","car_obs_CENTRAL":"Central de gran intuición para anticiparse, lectura de juego impecable y muy buena salida de balón para jugar tanto en corto cómo en largo, su pie izquierdo es prolijo, muestra bastante personalidad a pesar de ser jóven, se comunica permanentemente con su defensa, su techo es alto y sin duda está para grandes retos y dar el salto de calidad.","car_obs_central":"Central de gran intuición para anticiparse, lectura de juego impecable y muy buena salida de balón para jugar tanto en corto cómo en largo, su pie izquierdo es prolijo, muestra bastante personalidad a pesar de ser jóven, se comunica permanentemente con su defensa, su techo es alto y sin duda está para grandes retos y dar el salto de calidad."}'),
